import{d as r,C as s,o as d,c as g,a3 as t,E as e,j as n,a as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第二十章","description":"《正易心法》第二十章——六十四卦，唯乾与坤：太始气之始为乾、形之始为坤，本之自然、无所假合，其卦画纯一不驳、倒正不变，是名真体。","frontmatter":{"title":"正易心法·第二十章","description":"《正易心法》第二十章——六十四卦，唯乾与坤：太始气之始为乾、形之始为坤，本之自然、无所假合，其卦画纯一不驳、倒正不变，是名真体。","category":"guide","aliases":["正易心法第二十章","六十四卦唯乾与坤","真体"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-20.md","filePath":"yijing/zheng-yi-xin-fa/chapter-20.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-20.md"},k=r({...c,setup(u){const i=[{id:"z20-01",label:"一、唯乾坤为真体",showLabel:!0,sentences:[["六十四卦，唯乾与坤。本之自然，是名",{text:"真体",glossary:"zhenti"},"。"]],note:["六十四卦之中，只有乾与坤；它们根本于自然，这就叫做「真体」。（这是全书的哲学收束之一——**「真体」是对第九至十六章所有论述的最终命名**：第九章乾坤破体生六子（破体的来源）、第十章乾坤纯粹（纯体的价值）、第十一章破体炼之（归真的路径）、第十六章乾坤倒正不变（真体的特性），本章给出最终的名字。）"]},{id:"z20-02",label:"二、气之始与形之始",showLabel:!0,sentences:[[{text:"太始",glossary:"taishi"},"者，气之始，是为乾。太始者，形之始，是为坤。"]],note:["太始，是气的开始，这就是乾；太始，是形的开始，这就是坤。（**这里原文两处都作「太始」，疑为传抄之误**——据《列子·天瑞》的宇宙生成序列：「太易（未见气）→ 太初（气之始）→ 太始（形之始）→ 太素（质之始）」，则「气之始」当为「太初」，「形之始」当为「太始」。**但意思很清楚：乾是气之初，坤是形之初**——乾坤不是圣人画出来的，而是宇宙生成过程中自然出现的结构：有气就有乾，有形就有坤。）"]},{id:"z20-03",label:"三、纯一不驳倒正不变",showLabel:!0,sentences:[["皆本之自然，无所",{text:"假合",glossary:"jiahe"},"也。故其卦画",{text:"纯一不驳",glossary:"chunyiBubo"},"，",{text:"倒正不变",glossary:"daozhengBubian"},"，是名真体。"]],note:["两者都根本于自然，没有借助任何东西拼合而成。因此它们的卦画纯粹统一、没有杂质，翻转与正立都不改变——这就叫做「真体」。（真体的四条完整定义：**① 本之自然**（来源：宇宙本原，非人为构造）；**② 无所假合**（结构：纯粹本质，非拼合而成）；**③ 纯一不驳**（卦画：六爻纯阳或纯阴）；**④ 倒正不变**（特性：翻转后仍是自身，即第十六章的「对体卦」）。对照六子：震坎艮巽离兑皆借乾坤之爻而成体，故曰「假合」。）"]}],o=[{id:"zhenti",term:"真体",pinyin:"zhēn tǐ",meaning:"真正的本体。相对于六子的「破体」，乾坤是未破之体。"},{id:"taishi",term:"太始",pinyin:"tài shǐ",meaning:"《列子·天瑞》宇宙生成序列之一。原文两处皆作「太始」，疑为传抄之误（气之始当为「太初」，形之始当为「太始」）。"},{id:"jiahe",term:"假合",pinyin:"jiǎ hé",meaning:"借助外力拼合而成。乾坤不需要借任何东西，故曰「无所假合」。"},{id:"chunyiBubo",term:"纯一不驳",pinyin:"chún yī bù bó",meaning:"纯粹统一，没有杂质。乾六爻全阳、坤六爻全阴，故纯一。驳是杂色。"},{id:"daozhengBubian",term:"倒正不变",pinyin:"dào zhèng bù biàn",meaning:"翻转与正立都不改变。即第十六章所说的「对体卦」特征。"}];return(b,a)=>{const l=s("DaoTextReading"),p=s("DaoKeywordCards");return d(),g("div",null,[a[0]||(a[0]=t(`<h1 id="正易心法·第二十章" tabindex="-1">正易心法·第二十章 <a class="header-anchor" href="#正易心法·第二十章" aria-label="Permalink to &quot;正易心法·第二十章&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>本章是全书的<strong>哲学收束之一</strong>，给出乾坤地位的最终命名：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>六十四卦中：</span></span>
<span class="line"><span>  乾坤 = 真体（本之自然，纯一不驳，倒正不变）</span></span>
<span class="line"><span>  其余六十二卦 = 破体（乾坤交合的产物）</span></span></code></pre></div><p><strong>「真体」是对第九至十六章所有论述的最终命名</strong>：</p><table tabindex="0"><thead><tr><th>章</th><th>内容</th></tr></thead><tbody><tr><td>第九章</td><td>乾坤破体生六子（破体的来源）</td></tr><tr><td>第十章</td><td>乾坤纯粹，圣贤之象（纯体的价值）</td></tr><tr><td>第十一章</td><td>破体炼之，纯体乃成（归真的路径）</td></tr><tr><td>第十六章</td><td>乾坤倒正不变（真体的特性）</td></tr><tr><td><strong>第二十章</strong></td><td><strong>乾坤是真体（最终命名）</strong></td></tr></tbody></table><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p><strong>「太始」与「太素」的来源</strong>——麻衣引《列子》道家宇宙论，为乾坤提供哲学基础：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>《列子·天瑞》的序列：</span></span>
<span class="line"><span>  太易（未见气）→ 太初（气之始）→ 太始（形之始）→ 太素（质之始）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>麻衣的对应：</span></span>
<span class="line"><span>  乾 = 气之始</span></span>
<span class="line"><span>  坤 = 形之始</span></span></code></pre></div><blockquote><p>注：原文两处皆作「太始」，疑为传抄之误——「气之始」当为「太初」，「形之始」当为「太始」。但意思很清楚：<strong>乾是气之初，坤是形之初</strong>，乾坤不是圣人发明的，是宇宙生成过程中自然出现的结构。</p></blockquote><p><strong>「无所假合」的深层含义</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>六子都是「假合」：</span></span>
<span class="line"><span>  震 = 坤体 + 乾初爻（借乾一爻入坤）</span></span>
<span class="line"><span>  坎 = 坤体 + 乾中爻</span></span>
<span class="line"><span>  艮 = 坤体 + 乾上爻</span></span>
<span class="line"><span>  ……皆借乾坤之爻而成体</span></span>
<span class="line"><span></span></span>
<span class="line"><span>乾坤本身：</span></span>
<span class="line"><span>  乾 = 纯阳，不需要借任何东西</span></span>
<span class="line"><span>  坤 = 纯阴，不需要借任何东西</span></span>
<span class="line"><span>  = 无所假合 = 自足的本体</span></span></code></pre></div><p><strong>真体的完整定义（四条）</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 本之自然（来源）：宇宙本原，非人为构造</span></span>
<span class="line"><span>② 无所假合（结构）：纯粹本质，非拼合而成</span></span>
<span class="line"><span>③ 纯一不驳（卦画）：六爻纯阳或纯阴，无杂质</span></span>
<span class="line"><span>④ 倒正不变（特性）：翻转后仍是自身，永恒稳定</span></span></code></pre></div><p><strong>与《系辞传》的视角差异</strong>：</p><table tabindex="0"><thead><tr><th>视角</th><th>《系辞传》</th><th>麻衣道者</th></tr></thead><tbody><tr><td>乾坤的地位</td><td>「乾坤，其易之门邪」（入口）</td><td>真体，六十四卦的本原（终点）</td></tr><tr><td>乾坤的来源</td><td>圣人仰观俯察而画卦</td><td>太始太素，本之自然</td></tr><tr><td>方向</td><td>乾坤→万卦（向外展开）</td><td>万卦→乾坤（向内收束）</td></tr></tbody></table><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>注意「真体」这个命名的分量：<strong>它把乾坤从「两个卦」升为「本体」</strong>；</li><li>对照六子的「假合」：<strong>乾坤自足，六子借体</strong>；</li><li>记住四条定义：<strong>本之自然、无所假合、纯一不驳、倒正不变。</strong></li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>唯乾坤</strong>：六十四卦只有乾坤是真体。</li><li><strong>太始</strong>：气之始为乾，形之始为坤。</li><li><strong>本之自然</strong>：宇宙本原，非人为构造。</li><li><strong>无所假合</strong>：不借他物，自足本体。</li><li><strong>纯一不驳</strong>：六爻纯阳或纯阴。</li><li><strong>倒正不变</strong>：即「对体卦」特征。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>`,21)),e(l,{colophon:"唯乾与坤 · 本之自然 · 纯一不驳 · 倒正不变",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第二十章原文",sections:i,glossary:o}),a[1]||(a[1]=n("blockquote",null,[n("p",null,"注：本页依所据底本录入。原文两处「太始」疑为传抄之误（参《列子·天瑞》：太初为气之始、太始为形之始），此处依底本录入、以上文说明校勘意见，不作径改。")],-1)),a[2]||(a[2]=n("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),n("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(p,{items:[{term:"真体",pinyin:["zhēn","tǐ"],meaning:"真正的本体。相对于六子的「破体」，乾坤是未破之体。"},{term:"本之自然",pinyin:["běn","zhī"],meaning:"根本于自然，不是人为构造。乾坤是宇宙生成过程中自然出现的结构。"},{term:"无所假合",pinyin:["wú","suǒ"],meaning:"不借助任何东西拼合。六子皆借乾坤之爻而成体，唯乾坤自足。"},{term:"纯一不驳",pinyin:["chún","yī"],meaning:"纯粹统一，没有杂质。乾六爻全阳、坤六爻全阴。"},{term:"倒正不变",pinyin:["dào","zhèng"],meaning:"翻转与正立都不改变——即第十六章所说的「对体卦」特征。"}]}),a[3]||(a[3]=t(`<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章在说什么" tabindex="-1">象：这一章在说什么 <a class="header-anchor" href="#象-这一章在说什么" aria-label="Permalink to &quot;象：这一章在说什么&quot;">​</a></h3><p>本章是全书的<strong>哲学收束之一</strong>，给出乾坤地位的最终命名：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>乾坤 = 真体（本之自然，纯一不驳，倒正不变）</span></span>
<span class="line"><span>其余六十二卦 = 破体（乾坤交合的产物）</span></span></code></pre></div><h3 id="理-为什么这样说" tabindex="-1">理：为什么这样说 <a class="header-anchor" href="#理-为什么这样说" aria-label="Permalink to &quot;理：为什么这样说&quot;">​</a></h3><p><strong>「太始」的来源</strong>——麻衣引《列子》道家宇宙论，为乾坤提供哲学基础：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>《列子·天瑞》：太易（未见气）→ 太初（气之始）→ 太始（形之始）→ 太素（质之始）</span></span>
<span class="line"><span>麻衣的对应：乾 = 气之始；坤 = 形之始</span></span>
<span class="line"><span></span></span>
<span class="line"><span>（原文两处皆作「太始」，疑为传抄之误，但意思很清楚）</span></span></code></pre></div><p><strong>「无所假合」的深层含义</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>六子都是「假合」：震 = 坤体 + 乾初爻……皆借乾坤之爻而成体</span></span>
<span class="line"><span>乾坤本身：纯阳、纯阴，不借任何东西 = 无所假合 = 自足的本体</span></span></code></pre></div><p><strong>真体的四条定义</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 本之自然（来源）② 无所假合（结构）③ 纯一不驳（卦画）④ 倒正不变（特性）</span></span></code></pre></div><p><strong>与《系辞传》的视角差异</strong>：《系辞》说「乾坤，其易之门邪」（入口）；麻衣说乾坤是<strong>真体，六十四卦的本原</strong>（终点）。前者向外展开（乾坤→万卦），后者向内收束（万卦→乾坤）。</p><h3 id="用-今天怎么进入这一章" tabindex="-1">用：今天怎么进入这一章 <a class="header-anchor" href="#用-今天怎么进入这一章" aria-label="Permalink to &quot;用：今天怎么进入这一章&quot;">​</a></h3><ul><li>注意「真体」这个命名的分量：<strong>它把乾坤从「两个卦」升为「本体」</strong>；</li><li>对照六子的「假合」：<strong>乾坤自足，六子借体</strong>；</li><li>记住四条定义，<strong>它们是检验一个东西「是不是真体」的标准</strong>。</li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>六十四卦之中，只有乾与坤；它们根本于自然，这就叫做「真体」。</p><p>太始，是气的开始，这就是乾；太始，是形的开始，这就是坤。</p><p>两者都根本于自然，没有借助任何东西拼合而成。因此它们的卦画纯粹统一、没有杂质，翻转与正立都不改变——这就叫做「真体」。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：第二十章只做了一件事——<strong>给乾坤发了一张身份证，名字叫「真体」。</strong></p></blockquote><p>可以按这几条慢慢写：</p><ul><li><strong>「真体」这个命名</strong>——它把乾坤从「卦」升为「本体」。<strong>注意这个顺序：麻衣先讲了十九章的各种变法，最后才给乾坤命名。</strong> 命名放在最后，是因为只有看遍了「假合」，才认得出什么是「真」。</li><li><strong>「无所假合」</strong>——这是最要紧的一条。<strong>六子都借了乾坤的爻，只有乾坤不借别人的。</strong> 借来的东西，再好看也是借来的。<strong>这让我想到一个问题：我身上有多少是「借来的体」？</strong></li><li><strong>「纯一不驳」</strong>——乾是全阳，坤是全阴。<strong>「纯」不是「多」，是「不杂」。</strong> 这与第十章「圣贤各尽一道」是同一件事。</li><li><strong>「倒正不变」</strong>——翻转过来还是自己。<strong>这就是第十六章的「对体卦」。</strong> 麻衣在这里把它和「真体」连上了：<strong>因为纯，所以不变；因为不变，所以是真。</strong></li><li><strong>「太始」的问题</strong>——原文两处都写「太始」，按《列子》应当是「太初」为气之始、「太始」为形之始。<strong>这可能真是传抄之误。</strong> 但有意思的是：<strong>麻衣自己批评别人「袭谬承误」（第四十二章），而我们读麻衣，也要带着同样的眼光。</strong> 这不是不敬，这正是他要的。</li><li><strong>留给自己的问题</strong>（承接昇哥的钩子）：<strong>麻衣说「太始者，形之始，是为坤」——用了同一个「太始」；这是麻衣原文，还是传抄者的错误？而如果我们读麻衣也需要「质疑文本本身」，那么「义实通明」是否也包括「质疑我所读的这本书」？</strong> 我的答案：<strong>是的，而且这正是麻衣自己的方法</strong>——他在第二十三章就曾指出《序卦传》《说卦传》有传抄之误。<strong>一部反对「盲诵」的书，也要求读者不盲诵它自己。</strong> 这大概是《正易心法》最彻底的地方。</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/">正易心法总览</a></li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-09">第九章 · 乃生六子</a> — 破体（「真体」的对立面）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-10">第十章 · 即是阴阳</a> — 纯而不驳（真体的价值）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-11">第十一章 · 偏陂反侧</a> — 破体炼之（归真的路径）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-16">第十六章 · 卦有反对</a> — 对体八卦（「倒正不变」的出处）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-21">第二十一章 · 六子假合</a> — 与本章构成「真体／假合」的最终对照</li></ul>`,24))])}}});export{y as __pageData,k as default};
